	private static long arrayBytes(long length, long width) {
		if (length < 0L || length > Integer.MAX_VALUE - 8L || length > (Long.MAX_VALUE - 31L) / width) {
			return -1L;
		}
		return (24L + width * length + 7L) & ~7L;
	}

